export function getCampaignIcon(code: string): string | undefined {
  const key = code?.toUpperCase()?.trim();
  if (!key) return undefined;
  // Direct match first
  if (PRODUCT_ICONS[key]) return PRODUCT_ICONS[key];
  if (CATEGORY_ICONS[key]) return CATEGORY_ICONS[key];
  // Alias lookup
  const aliasKey = CODE_ALIASES[key];
  if (aliasKey) return PRODUCT_ICONS[aliasKey] ?? CATEGORY_ICONS[aliasKey];
  return undefined;
}
